import { useState } from 'react'
import { Button, Icon, Modal } from 'antd'

const ViewDocumentsModal = ({ documents, downloadRequest }) => {
  const [visible, toggleModal] = useState(false)
  return (
    <div>
      {
        Array.isArray(documents) && (
          <div>
            {documents.length}
            <Button
              onClick={() => toggleModal(true)}
              disabled={!documents.length}
              type='link'
            >
              | View Documents <Icon type='eye' />
            </Button>
          </div>
        )
      }
      <Modal
        visible={visible}
        onCancel={() => toggleModal(false)}
        onOk={() => toggleModal(false)}
        title='Uploaded Documents'
      >
        {
          Array.isArray(documents) && documents.map((file, index) => (
            <div
              key={file}
            >
              <Button
                type='link'
                className={index > 0 ? 'mt-5' : ''}
                onClick={() => {
                  const fileName = file && file.split(':')[2]
                  downloadRequest({
                    action_type: 'GET',
                    identifier: 'quotation',
                    file_name: fileName
                  })
                }}
              >
                Document {index + 1} <Icon type='download' />
              </Button>
            </div>
          ))
        }
      </Modal>
    </div>
  )
}
export default ViewDocumentsModal
