import { Button, Icon } from 'antd'

const renderProducts = (product, leadConfigData) => {
  return product?.map(item => {
    const itemConfig = leadConfigData?.products.find(({ code }) => code === item)
    return itemConfig ? itemConfig.name : item
  })
    .join(', ')
}

const renderChannel = (channel, leadConfigData) => {
  return leadConfigData?.channels?.find(({ code }) => code === channel)?.name || channel
}

export const quickLookDataGenertator = ({
  caseId,
  CompanyName,
  quotationCount,
  product,
  effectiveDate,
  endDate,
  participantsCount,
  picPhone,
  picEmail,
  picName,
  setDataToShow,
  toggleDetailVisibility,
  leadConfigData
}) => [
  [
    { label: 'Case ID', value: caseId },
    { label: 'PIC', value: picName },
    { label: 'Effective Date', value: effectiveDate }
  ], // Row 1
  [
    { label: 'Company Name', value: CompanyName },
    { label: 'PIC Email', value: picEmail },
    {
      label: 'Product',
      value: renderProducts(product, leadConfigData)
    }
  ], // Row 2
  [
    { label: 'Quotation Count', value: quotationCount },
    { label: 'PIC Phone', value: picPhone },
    {
      label: (
        <Button
          onClick={() => toggleDetailVisibility(true)}
          type='link'
        >
          more <Icon type='double-right' />
        </Button>)
    }
  ] // Row 3
]
