import ebUrls from '../../../../../request/urls/employeeBenefit'

const actions = {
  CASE_DETAIL_REQUEST: 'CASE_DETAIL_REQUEST',
  CASE_DETAIL: 'CASE_DETAIL',
  QUOTATION_LIST_REQUEST: 'QUOTATION_LIST_REQUEST',
  QUOTATION_LIST: 'QUOTATION_LIST',
  caseDetailRequest: payload => ({
    type: actions.CASE_DETAIL_REQUEST,
    payload: {
      ...payload,
      method: 'get',
      url: ebUrls.getCaseDetail
    }
  }),
  quotationListRequest: payload => ({
    type: actions.QUOTATION_LIST_REQUEST,
    payload: {
      ...payload,
      method: 'get',
      url: ebUrls.getQuotationList
    }
  })
}

export default actions
