import { useErrorContextValue, useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import {
  Col,
  Table,
  Spin,
  Alert
} from 'antd'
import { useEffect, useState } from 'react'
import { useParams } from 'react-router'
import { EbSectionWrapper } from '../../../CommonComponents'
import {
  RowWithMargin
} from '../../../CommonComponents/index.style'
import BackButton from '../../../components/BackButton'
import { useDownloadFileFromGcs, useLeadConfig } from '../../../state/hooks'
import { useQuotationList } from '../../../state/QuotationDetail/hooks/useQuotationDetail'
import CaseDetail from './components/CaseDetail'
import { quotationSummaryColumns } from './utility'

const QuotationDataSummary = ({ history }) => {
  const { quotationListData, quotationListRequest } = useQuotationList()
  const { downloadRequest } = useDownloadFileFromGcs()
  const [{
    QUOTATION_LIST_LOADER
  }] = useLoaderContextValue()
  const { leadConfigRequest, leadConfigData } = useLeadConfig()
  const [{
    QUOTATION_LIST_ERROR,
    quotationListStatus
  }] = useErrorContextValue()
  const [listMetaData, setListMetaData] = useState({})
  const params = useParams()

  const editQuotation = quotationData => history.push({
    pathname: `/employee-benefits/edit-quotation/${quotationData?.id}`
  })

  const handleTableChange = (params) => {
    const query = {
      page: params.current,
      per_page: params.pageSize
    }
    quotationListRequest({ ...query })
  }

  useEffect(() => {
    if (quotationListData && quotationListData.meta_data) {
      setListMetaData(quotationListData.meta_data)
    }
  }, [quotationListData])

  useEffect(() => {
    leadConfigRequest()
    quotationListRequest({ case_id: params.caseId })
  }, [leadConfigRequest, quotationListRequest, params])

  return (
    <>
      <BackButton />
      {QUOTATION_LIST_ERROR && <Alert type='error' message={quotationListStatus} banner />}
      <CaseDetail />
      <EbSectionWrapper>
        <Spin spinning={!!QUOTATION_LIST_LOADER}>
          <RowWithMargin gutter={16}>
            <Col span={24}>
              <Table
                rowKey={({ id: quotationId }) => `quotation-${quotationId}`}
                columns={quotationSummaryColumns({ editQuotation, downloadRequest, leadConfigData })}
                dataSource={quotationListData ? quotationListData.data : []}
                bordered
                onChange={handleTableChange}
                pagination={{
                  pageSize: listMetaData.page_size,
                  total: listMetaData.total_records,
                  current: listMetaData.page
                }}
                scroll={{ x: true }}
              />
            </Col>
          </RowWithMargin>
        </Spin>
      </EbSectionWrapper>
    </>
  )
}
export default QuotationDataSummary
