import { useErrorContextValue, useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import { Alert, Button, Col, Icon, Modal, Row, Spin, Typography } from 'antd'
import { useCallback, useEffect, useState } from 'react'
import { useHistory, useParams } from 'react-router'
import { EbSectionWrapper, RowWithMargin } from '../../../../../CommonComponents'
import { ColTextAlignRight } from '../../../../../CommonComponents/index.style'
import ButtonWithPermission from '../../../../../components/ButtonWithPermission'
import { useDownloadFileFromGcs, useLeadConfig } from '../../../../../state/hooks'
import { useQuotationDetail } from '../../../../../state/QuotationDetail/hooks/useQuotationDetail'
import { caseDetailDataForModalGenerator, quickLookDataGenertator } from './constants'
import { CaseDetailContainer, ModalContentWrapper } from './index.style'

const { Text, Title } = Typography

const CaseDetail = () => {
  const { caseDetailData, caseDetailRequest } = useQuotationDetail()
  const [detailVisibile, toggleDetailVisibility] = useState(false)
  const { leadConfigData, leadConfigRequest } = useLeadConfig()
  const params = useParams()
  const { downloadRequest } = useDownloadFileFromGcs()
  const history = useHistory()
  const [{ DOWNLOAD_FILE_FROM_GCS_ERROR, downloadFileFromGcsStatus, CASE_DETAIL_ERROR, caseDetailStatus }] = useErrorContextValue()
  const [{ CASE_DETAIL_LOADER }] = useLoaderContextValue()

  const {
    id: caseId,
    company_name: CompanyName,
    quotation_count: quotationCount,
    product,
    effective_date: effectiveDate,
    end_date: endDate,
    pic_phone: picPhone,
    pic_email: picEmail,
    pic_name: picName,
    channel,
    business_type: lineOfBusiness,
    agent,
    sub_offices: subOffices,
    participant_count: participantsCount,
    existing_insurance_provider: existingInsurance,
    budget,
    existing_broker: existingBroker,
    documents,
    case_status: caseStatus
  } = caseDetailData || {}

  const detailData = quickLookDataGenertator({
    CompanyName,
    caseId,
    quotationCount,
    product,
    effectiveDate,
    picName,
    picEmail,
    picPhone,
    participantsCount,
    toggleDetailVisibility,
    leadConfigData
  })

  const caseDetailDataForModal = caseDetailDataForModalGenerator({
    caseId,
    CompanyName,
    quotationCount,
    product,
    effectiveDate,
    endDate,
    participantsCount,
    picPhone,
    picEmail,
    picName,
    subOffices,
    lineOfBusiness,
    agent,
    existingInsurance,
    budget,
    existingBroker,
    channel,
    leadConfigData
  })

  const editCase = useCallback(caseData => {
    history.push({
      pathname: `/employee-benefits/edit-case/${caseData.id}`
    })
  }, [history])

  useEffect(() => {
    const { caseId } = params
    caseDetailRequest({ id: caseId })
    leadConfigRequest()
  }, [caseDetailRequest, params, leadConfigRequest])

  return (
    <EbSectionWrapper>
      {CASE_DETAIL_ERROR && <Alert type='error' message={caseDetailStatus} banner />}
      <Spin spinning={!!CASE_DETAIL_LOADER}>
        <CaseDetailContainer>
          <Row gutter={16} className='mb-5'>
            <Col span={8}><h2>Case Details</h2></Col>
            <ColTextAlignRight span={12}>
              <ButtonWithPermission
                type='primary'
                onClick={() => editCase(caseDetailData)}
                requiredPermission='ops.eb_update_case'
              >
                <Icon type='edit' /> Case
              </ButtonWithPermission>
            </ColTextAlignRight>
            <ColTextAlignRight span={4}>
              <ButtonWithPermission
                disabled={['CLOSING', 'LOSING'].includes(caseStatus)}
                type='primary'
                onClick={() => history.push({
                  pathname: '/employee-benefits/add-quotation',
                  state: { case_id: params.caseId }
                })}
                requiredPermission='ops.eb_update_quotation'
              >
                Add Quotation <Icon type='plus' />
              </ButtonWithPermission>
            </ColTextAlignRight>
          </Row>
          {detailData.map((rowData, rowIndex) => (
            <RowWithMargin key={rowIndex} span={8} gutter={16}>
              {
                rowData.map(({ label, value }, index) => (
                  <Col span={8} key={label}>
                    <Row>
                      <Col span={12}><Text strong>{label}</Text></Col>
                      <Col span={12}>{value}</Col>
                    </Row>
                  </Col>
                ))
              }
            </RowWithMargin>
          ))}
          <Modal
            visible={detailVisibile}
            width={800}
            title='Case Detail'
            onCancel={() => toggleDetailVisibility(false)}
          >
            {DOWNLOAD_FILE_FROM_GCS_ERROR && <Alert type='error' message={downloadFileFromGcsStatus} banner />}
            <Title level={4}>Info</Title>
            <RowWithMargin>
              {caseDetailDataForModal.map((rowData, rowIndex) => (
                <RowWithMargin key={rowIndex} span={12}>
                  {
                    rowData.map(({ label, value }, colIndex) => (
                      <Col span={12} key={colIndex}>
                        <Row>
                          <Col span={12}><Text strong>{label}</Text></Col>
                          <Col span={12}>{value}</Col>
                        </Row>
                      </Col>
                    ))
                  }
                </RowWithMargin>
              ))}
            </RowWithMargin>
            <Title level={4}>Documents</Title>
            <div>
              {
                Array.isArray(documents) && documents.map((file, index) => (
                  <ModalContentWrapper
                    key={file}
                    className='no-padding'
                  >
                    <Button
                      type='link'
                      className={index > 0 ? 'mt-5 no-padding' : 'no-padding'}
                      onClick={() => {
                        const fileName = file && file.split(':')[2]
                        downloadRequest({
                          action_type: 'GET',
                          identifier: 'case',
                          file_name: fileName
                        })
                      }}
                    >
                      Document {index + 1} <Icon type='download' />
                    </Button>
                  </ModalContentWrapper>
                ))
                }
            </div>
          </Modal>
        </CaseDetailContainer>
      </Spin>
    </EbSectionWrapper>
  )
}
export default CaseDetail
