import { Col, Icon, Row, Tag } from 'antd'
import moment from 'moment'
import { formatIntl } from '../../../../../../helpers/utility'
import ebUrls from '../../../../../../request/urls/employeeBenefit'
import ButtonWithPermission from '../../../components/ButtonWithPermission'
import CaseQuotatoinRemarks from '../../../components/CaseQuotationRemarks'
import { businessDiff, mapCodeToNameFromLeadConfigData } from '../../../utils/helpers'
import TruncatedNotes from './components/TruncatedNotes'
import ViewDocumentsModal from './components/ViewDocumentsModal/inex'

export const quotationSummaryColumns = ({ editQuotation, downloadRequest, leadConfigData }) => [
  {
    title: 'Actions',
    width: 160,
    key: 'actions',
    render: (rowData) => (
      <>
        <Row className='mb-5'>
          <Col span={10}>
            <ButtonWithPermission
              type='primary'
              onClick={() => editQuotation(rowData)}
              requiredPermission='ops.eb_update_quotation'
            >
              <Icon type='edit' /> Quotation
            </ButtonWithPermission>
          </Col>
        </Row>
      </>
    )
  },
  {
    title: 'Quotation ID',
    dataIndex: 'id',
    width: 100
  },
  {
    title: 'Insurance Provider',
    dataIndex: 'insurance_provider',
    width: 120
  },
  {
    title: 'Request From Marketing',
    dataIndex: 'marketing_request_date',
    width: 150,
    render: requestFromMarketingDate => requestFromMarketingDate && moment(requestFromMarketingDate).format('DD MMM, YYYY')
  },
  {
    title: 'TAT1',
    dataIndex: 'tat1',
    render: (tat1, rowData) => {
      tat1 = tat1 === 0 ? '0' : tat1
      if (!tat1 && rowData.marketing_request_date) {
        tat1 = businessDiff(moment(rowData.marketing_request_date), moment())
      }
      return tat1 ? <Tag color={Number(tat1) >= 2 ? 'volcano' : 'green'}>{tat1}</Tag> : <Tag>-</Tag>
    },
    width: 100,
    align: 'right'
  },
  {
    title: 'Booking To Insurer',
    dataIndex: 'insurer_booking_date',
    width: 150,
    render: bookingToInsurerDate => bookingToInsurerDate && moment(bookingToInsurerDate).format('DD MMM, YYYY')
  },
  {
    title: 'TAT2',
    dataIndex: 'tat2',
    render: (tat2, rowData) => {
      tat2 = tat2 === 0 ? '0' : tat2
      if (!tat2 && rowData.insurer_booking_date) {
        tat2 = businessDiff(moment(rowData.insurer_booking_date), moment())
      }
      return tat2 ? <Tag color={Number(tat2) >= 6 ? 'volcano' : 'green'}>{tat2}</Tag> : <Tag>-</Tag>
    },
    width: 100,
    align: 'right'
  },
  {
    title: 'Data Sent to Insurer',
    dataIndex: 'insurer_data_sent_date',
    width: 150,
    render: dataSentToInsurerDate => dataSentToInsurerDate && moment(dataSentToInsurerDate).format('DD MMM, YYYY')
  },
  {
    title: 'TAT3',
    dataIndex: 'tat3',
    width: 100,
    align: 'right',
    render: (tat3, rowData) => {
      tat3 = tat3 === 0 ? '0' : tat3
      if (!tat3 && rowData.insurer_data_sent_date) {
        tat3 = businessDiff(moment(rowData.insurer_data_sent_date), moment())
      }
      return tat3 ? <Tag color={Number(tat3) >= 6 ? 'volcano' : 'green'}>{tat3}</Tag> : <Tag>-</Tag>
    }
  },
  {
    title: 'Quotation Received From Insurer',
    dataIndex: 'quotation_received_date',
    width: 150,
    render: quotationReceivedDate => quotationReceivedDate && moment(quotationReceivedDate).format('DD MMM, YYYY')
  },
  {
    title: 'Premi Release From Insurance (Rp)',
    dataIndex: 'premium',
    width: 120,
    align: 'right',
    render: premium => (premium && formatIntl(premium)) || '-'
  },
  {
    title: 'Notes',
    dataIndex: 'notes',
    width: 200,
    render: (notes) => <TruncatedNotes notes={notes} />
  },
  {
    title: 'Quotation Status',
    dataIndex: 'quotation_status',
    width: 150,
    render: quotationStatus => mapCodeToNameFromLeadConfigData(quotationStatus, 'quotation_status', leadConfigData)
  },
  {
    title: 'Document Received',
    dataIndex: 'documents',
    render: (documents) => <ViewDocumentsModal documents={documents} downloadRequest={downloadRequest} />,
    width: 240
  },
  {
    title: 'Money In',
    dataIndex: 'money_in_date',
    width: 120,
    render: moneyInDate => moneyInDate && moment(moneyInDate).format('DD MMM, YYYY')
  },
  {
    title: 'Create At',
    dataIndex: 'created_at',
    width: 120,
    render: createdAtDate => createdAtDate && moment(createdAtDate).format('DD MMM, YYYY')
  },
  {
    title: 'Status Updated At',
    dataIndex: 'quotation_status_updated_date',
    width: 120,
    render: statusUpdatedAtDate => statusUpdatedAtDate && moment(statusUpdatedAtDate).format('DD MMM, YYYY')
  },
  {
    title: 'Remarks',
    widht: 200,
    render: ({ id }) => <CaseQuotatoinRemarks url={ebUrls.quotationRemarks} id={id} />
  }
]
