import { useServiceRequest } from '@pasarpolis/common-react-hooks'
import { useCallback } from 'react'
import { useEBContextValue } from '../../../context/index'
import actions from '../actions'

export const useQuotationSummary = () => {
  const [{ quotationSummaryData }, dispatch] = useEBContextValue()
  const [callApi] = useServiceRequest(dispatch)
  const quotationSummaryRequest = useCallback((payload = {}) => {
    callApi(actions.getQuotationSummary({ query: payload }))
  }, [callApi])
  return { quotationSummaryData, quotationSummaryRequest }
}

