import { Button, Modal } from 'antd'
import React, { useState } from 'react'

const TruncatedNotes = ({ notes }) => {
  const [visible, toggleVisible] = useState(false)
  let displayNotes = ''
  const notesWithoutLineBreaks = notes && String(notes).split('\n').join(' ')
  if (notesWithoutLineBreaks?.length > 35) {
    displayNotes = String(notes).substring(0, 28)
  } else {
    displayNotes = notesWithoutLineBreaks
  }
  return (
    <>
      {notesWithoutLineBreaks?.length > 35
        ? (
          <>
            {displayNotes}
            <Button
              size='small'
              type='link'
              onClick={() => toggleVisible(true)}
            >
              ... more
            </Button>
          </>
          )
        : displayNotes}
      <Modal
        visible={visible}
        title='Notes'
        onOk={() => toggleVisible(false)}
        onCancel={() => toggleVisible(false)}
      >
        {notes}
      </Modal>
    </>
  )
}
export default TruncatedNotes
